fn sort(a: Vec<Int>) -> Vec<Int> {
    let mut result = a
    let n = len(&result)
    for i in range(0, n) {
        let mut min_idx = i
        for j in range(i + 1, n) {
            if result.get(j) < result.get(min_idx) {
                min_idx = j
            }
        }
        if min_idx != i {
            let temp = result.get(min_idx)
            result.set(min_idx, result.get(i))
            result.set(i, temp)
        }
    }
    result
}

