    print(palindrome("level"))    // true
    print(palindrome("stereo"))   // false
    print(palindrome("rotor"))    // true
}

fn is_palindrome(s: Str) -> Bool {
    let len = str_len(s)
    let mut i = 0
    let mut j = len - 1
    while i < j {
        if s.charAt(i) != s.charAt(j) {
            return false
        }
        i = i + 1
        j = j - 1
    }
    true
}

